// ------------------------------------------------------------------
// Placeholder for the embedded web bundle. Regenerated by
// scripts/gen-web-assets.ts after `bun --cwd web run build`, which is
// what CI does before `bun build --compile`. Running from source
// without regenerating it lands here, so ASSETS is empty and serve.ts
// falls back to web/dist on disk (Tier 2) or the GitHub release
// bundle (Tier 3) instead of crashing on a missing import.
// ------------------------------------------------------------------

export const ASSETS: Record<string, string> = {};

export const ASSETS_GENERATED_AT: number | null = null;
